// Headless regression tests for the baked native hand mesh asset (GH #55/#46).
//
// Consumes src/hook/native_hand_mesh_data.h (generated by tools/xmd_bake.py)
// through the public native_hand_mesh.h API. No GL context, no game install,
// no input synthesis -- pure data validation so the bake can never silently
// drift from the shipped .xmd geometry.

#include "native_hand_mesh.h"

#include <cmath>
#include <cstdio>

using RiddickVR::FindNativeHandMesh;
using RiddickVR::NativeHandMesh;
using RiddickVR::NativeHandMeshAt;
using RiddickVR::NativeHandMeshCount;

namespace {

int Fail(const char* what, const char* name) {
    std::fprintf(stderr, "native hand mesh: %s (%s)\n", what,
                 name ? name : "?");
    return 1;
}

bool Finite(float v) {
    return std::isfinite(v);
}

float Length3(const float* v) {
    return std::sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

// Counts frozen from the committed manifest
// (docs/rea/reference/native_hand_mesh.json); if the bake changes, this fails
// on purpose so the asset is re-derived and re-reviewed.
struct Expected {
    const char* name;
    unsigned int vertices;
    unsigned int index_count;
    int surface_index;
    int arm_axis;   // GH #64: baked model-space long axis (0/1/2)
};

const Expected kExpected[] = {
    { "Riddick_LeftArm", 526, 2421, 1, 1 },
    { "Riddick_RightArm", 344, 1641, 2, 1 },
    { "Pa2_Hand", 138, 540, 0, 1 },
    { "Pa2_Hand_Detail", 540, 3228, 0, 1 },
};

} // namespace

int main() {
    const int count = NativeHandMeshCount();
    if (count < static_cast<int>(sizeof(kExpected) / sizeof(kExpected[0]))) {
        return Fail("fewer baked meshes than expected", nullptr);
    }

    for (int i = 0; i < count; ++i) {
        const NativeHandMesh& mesh = NativeHandMeshAt(i);
        if (!mesh.name || mesh.name[0] == '\0') {
            return Fail("empty mesh name", nullptr);
        }
        if (!mesh.vertices || !mesh.indices) {
            return Fail("null geometry pointer", mesh.name);
        }
        if (mesh.vertex_count == 0 || mesh.index_count == 0) {
            return Fail("empty geometry", mesh.name);
        }
        if (mesh.index_count % 3 != 0) {
            return Fail("index count is not a triangle multiple", mesh.name);
        }
        // Unique name lookup resolves to the same mesh.
        const NativeHandMesh* found = FindNativeHandMesh(mesh.name);
        if (found != &mesh) {
            return Fail("name lookup mismatch", mesh.name);
        }

        unsigned int min_index = 0xFFFFFFFFu;
        unsigned int max_index = 0;
        for (unsigned int k = 0; k < mesh.index_count; ++k) {
            unsigned int idx = mesh.indices[k];
            if (idx >= mesh.vertex_count) {
                return Fail("index out of range", mesh.name);
            }
            if (idx < min_index) min_index = idx;
            if (idx > max_index) max_index = idx;
        }
        if (min_index != 0 || max_index != mesh.vertex_count - 1) {
            return Fail("indices do not cover every vertex (sparse bake)",
                       mesh.name);
        }

        // Every vertex finite, normals unit length, AABB agrees with data.
        float mn[3] = { 1e30f, 1e30f, 1e30f };
        float mx[3] = { -1e30f, -1e30f, -1e30f };
        for (unsigned int v = 0; v < mesh.vertex_count; ++v) {
            const auto& vert = mesh.vertices[v];
            for (int c = 0; c < 3; ++c) {
                if (!Finite(vert.position[c]) || !Finite(vert.normal[c])) {
                    return Fail("non-finite vertex data", mesh.name);
                }
                if (vert.position[c] < mn[c]) mn[c] = vert.position[c];
                if (vert.position[c] > mx[c]) mx[c] = vert.position[c];
            }
            float normal_len = Length3(vert.normal);
            if (std::fabs(normal_len - 1.0f) > 0.01f) {
                return Fail("non-unit vertex normal", mesh.name);
            }
        }
        for (int c = 0; c < 3; ++c) {
            if (mesh.bounds_min[c] > mesh.bounds_max[c]) {
                return Fail("inverted bounds", mesh.name);
            }
            if (std::fabs(mesh.bounds_min[c] - mn[c]) > 1e-3f ||
                std::fabs(mesh.bounds_max[c] - mx[c]) > 1e-3f) {
                return Fail("declared bounds disagree with vertices", mesh.name);
            }
        }

        // GH #58: an optional posed variant must share the topology, stay
        // finite, and declare its own (posed) bounds that agree with its
        // vertices. Absent poses are represented by a null pointer + "" source.
        if (mesh.has_pose()) {
            if (mesh.posed_vertices == nullptr) {
                return Fail("has_pose without posed vertices", mesh.name);
            }
            if (!mesh.pose_source || mesh.pose_source[0] == '\0') {
                return Fail("posed mesh without a pose source", mesh.name);
            }
            float pmn[3] = { 1e30f, 1e30f, 1e30f };
            float pmx[3] = { -1e30f, -1e30f, -1e30f };
            for (unsigned int v = 0; v < mesh.vertex_count; ++v) {
                const auto& vert = mesh.posed_vertices[v];
                for (int c = 0; c < 3; ++c) {
                    if (!Finite(vert.position[c]) || !Finite(vert.normal[c])) {
                        return Fail("non-finite posed vertex data", mesh.name);
                    }
                    if (vert.position[c] < pmn[c]) pmn[c] = vert.position[c];
                    if (vert.position[c] > pmx[c]) pmx[c] = vert.position[c];
                }
                float normal_len = Length3(vert.normal);
                if (std::fabs(normal_len - 1.0f) > 0.01f) {
                    return Fail("non-unit posed normal", mesh.name);
                }
            }
            for (int c = 0; c < 3; ++c) {
                if (mesh.posed_bounds_min[c] > mesh.posed_bounds_max[c]) {
                    return Fail("inverted posed bounds", mesh.name);
                }
                if (std::fabs(mesh.posed_bounds_min[c] - pmn[c]) > 1e-3f ||
                    std::fabs(mesh.posed_bounds_max[c] - pmx[c]) > 1e-3f) {
                    return Fail("declared posed bounds disagree with vertices",
                                mesh.name);
                }
            }
        } else if (mesh.posed_vertices != nullptr ||
                   (mesh.pose_source && mesh.pose_source[0] != '\0')) {
            return Fail("posed fields set without has_pose", mesh.name);
        }
    }

    // Frozen counts guard against silent asset drift.
    for (const Expected& e : kExpected) {
        const NativeHandMesh* mesh = FindNativeHandMesh(e.name);
        if (!mesh) {
            return Fail("expected mesh missing", e.name);
        }
        if (mesh->vertex_count != e.vertices ||
            mesh->index_count != e.index_count) {
            return Fail("vertex/index count drift", e.name);
        }
        if (mesh->surface_index != e.surface_index) {
            return Fail("surface index drift", e.name);
        }
        if (mesh->arm_axis != e.arm_axis) {
            return Fail("arm axis drift", e.name);
        }
        // GH #64: the baked axis must actually be the long direction of the file
        // geometry (guards the baked value against the source AABB).
        {
            const float ext[3] = {
                mesh->bounds_max[0] - mesh->bounds_min[0],
                mesh->bounds_max[1] - mesh->bounds_min[1],
                mesh->bounds_max[2] - mesh->bounds_min[2],
            };
            int longest = 0;
            if (ext[1] > ext[longest]) longest = 1;
            if (ext[2] > ext[longest]) longest = 2;
            if (mesh->arm_axis != longest) {
                return Fail("arm axis is not the file-geometry long axis", e.name);
            }
        }
    }

    // LOD pair shares the same bind-pose bounds.
    const NativeHandMesh* low = FindNativeHandMesh("Pa2_Hand");
    const NativeHandMesh* high = FindNativeHandMesh("Pa2_Hand_Detail");
    if (low && high) {
        for (int c = 0; c < 3; ++c) {
            if (std::fabs(low->bounds_min[c] - high->bounds_min[c]) > 1e-4f ||
                std::fabs(low->bounds_max[c] - high->bounds_max[c]) > 1e-4f) {
                return Fail("Pa2 hand LODs disagree on bounds", "Pa2_Hand");
            }
        }
    }

    // GH #58: the Riddick arm clusters carry a baked pose; the unskinned Pa2
    // hands do not. The posed geometry must actually differ from the bind pose
    // (a no-op pose would mean the clip failed to drive the arm bones).
    const char* kArms[] = { "Riddick_LeftArm", "Riddick_RightArm" };
    for (const char* arm : kArms) {
        const NativeHandMesh* mesh = FindNativeHandMesh(arm);
        if (!mesh || !mesh->has_pose()) {
            return Fail("expected a baked pose", arm);
        }
        float max_delta = 0.0f;
        for (unsigned int v = 0; v < mesh->vertex_count; ++v) {
            for (int c = 0; c < 3; ++c) {
                float d = std::fabs(mesh->posed_vertices[v].position[c] -
                                    mesh->vertices[v].position[c]);
                if (d > max_delta) max_delta = d;
            }
        }
        if (max_delta < 1.0f) {
            return Fail("posed geometry barely differs from bind", arm);
        }
    }
    const char* kUnskinned[] = { "Pa2_Hand", "Pa2_Hand_Detail" };
    for (const char* unskinned : kUnskinned) {
        const NativeHandMesh* mesh = FindNativeHandMesh(unskinned);
        if (mesh && mesh->has_pose()) {
            return Fail("unskinned cluster should not carry a pose", unskinned);
        }
    }

    // Clamped accessor never dangles; unknown names return null.
    const NativeHandMesh& clamped = NativeHandMeshAt(-1);
    if (&clamped != &NativeHandMeshAt(0)) {
        return Fail("negative index was not clamped", nullptr);
    }
    if (FindNativeHandMesh("does-not-exist") != nullptr) {
        return Fail("unknown name resolved", nullptr);
    }
    if (FindNativeHandMesh(nullptr) != nullptr) {
        return Fail("null name resolved", nullptr);
    }

    std::printf("native hand mesh: %d meshes ok\n", count);
    return 0;
}
